{"python":"import re

reported_ref = 'article:p35'
conf_acc_ref = 'supp.pdf/page4/R3C3'
conf_refs = [
    'supp.pdf/page4/R5C2', 'supp.pdf/page4/R5C3',
    'supp.pdf/page4/R7C2', 'supp.pdf/page4/R7C3'
]

def rows_of(file, sheet):
    try:
        return get_rows(file, sheet)
    except Exception:
        pass
    try:
        obj = tables[file][sheet]
        if isinstance(obj, dict):
            return obj.get('rows', [])
        return getattr(obj, 'rows', [])
    except Exception:
        return []

assay_map = {
    'Sensitive': 1, 'sensitive': 1, 'SENSITIVE': 1,
    'Resistant': 0, 'resistant': 0, 'RESISTANT': 0,
    'Sensitivity': 1, 'sensitivity': 1,
    'Resistance': 0, 'resistance': 0
}
truth_map = {'PR': 1, 'pr': 1, 'PD': 0, 'pd': 0}

candidates = []
seen = set()
scan_files = ['supp.pdf', 'mmc1.pdf', 'mmc2.pdf']

for fn in scan_files:
    if fn not in tables:
        continue
    sheets = list(tables[fn].keys()) if isinstance(tables[fn], dict) else []
    for sh in sheets:
        rows = rows_of(fn, sh)
        for ri, row in enumerate(rows, start=1):
            pid_cells, assay_cells, truth_cells = [], [], []
            for ci, raw in enumerate(row, start=1):
                if isinstance(raw, dict):
                    val = str(raw.get('value', '')).strip()
                    ref = raw.get('ref', '%s/%s/R%dC%d' % (fn, sh, ri, ci))
                else:
                    val = str(raw).strip()
                    ref = '%s/%s/R%dC%d' % (fn, sh, ri, ci)
                if not val:
                    continue
                if re.search(r'P-?\d+', val):
                    pid_cells.append((ref, val))
                if val in assay_map:
                    assay_cells.append((ref, val))
                if val in truth_map:
                    truth_cells.append((ref, val))
            if pid_cells and assay_cells and truth_cells:
                key = (pid_cells[0][0], assay_cells[0][0], truth_cells[0][0])
                if key in seen:
                    continue
                seen.add(key)
                pid_match = re.search(r'P-?\d+', pid_cells[0][1])
                pid = pid_match.group(0) if pid_match else '%s/%s/R%d' % (fn, sh, ri)
                candidates.append({
                    'id': '%s:%s/%s/R%d' % (pid, fn, sh, ri),
                    'score_ref': assay_cells[0][0],
                    'truth_ref': truth_cells[0][0],
                    'assay': assay_map[assay_cells[0][1]],
                    'truth': truth_map[truth_cells[0][1]]
                })
    if len(candidates) >= 54:
        break

# Prefer the primary supplement if it contains the complete matched table.
primary = [c for c in candidates if c['id'].split(':',1)[1].startswith('supp.pdf/')]
if len(primary) >= 54:
    candidates = primary[:54]

cm = {'TP': 0, 'FP': 0, 'FN': 0, 'TN': 0}
for c in candidates:
    if c['assay'] == 1 and c['truth'] == 1:
        cm['TP'] += 1
    elif c['assay'] == 1 and c['truth'] == 0:
        cm['FP'] += 1
    elif c['assay'] == 0 and c['truth'] == 1:
        cm['FN'] += 1
    else:
        cm['TN'] += 1

print('candidate_n=', len(candidates))
print('confusion=', cm)
print('first_candidates=', candidates[:10])

ok = len(candidates) == 54 and cm == {'TP': 21, 'FP': 5, 'FN': 4, 'TN': 24}
records = []
if ok:
    for c in candidates:
        records.append({
            'id': c['id'],
            'score': {'ref': c['score_ref'], 'map': {'Sensitive': 1, 'Resistant': 0, 'sensitive': 1, 'resistant': 0, 'SENSITIVE': 1, 'RESISTANT': 0, 'Sensitivity': 1, 'Resistance': 0, 'sensitivity': 1, 'resistance': 0}},
            'truth': {'ref': c['truth_ref'], 'map': {'PR': 1, 'PD': 0, 'pr': 1, 'pd': 0}}
        })

fields = {
    'unit': {'value': 'organoid_line', 'evidence': [reported_ref], 'explanation': 'The 83.3% accuracy denominator is 54 LCOs derived from 36 patients, rather than 54 independent patients.'},
    'platform': {'value': 'organoid', 'evidence': [reported_ref], 'explanation': 'Lung cancer organoid drug sensitivity testing.'},
    'readout': {'value': 'viability', 'evidence': ['article:p128'], 'explanation': 'The predictor is the day-4 ATP luminance ratio of treated to untreated organoids.'},
    'direction': {'value': 'lower_sensitive', 'evidence': ['article:p128'], 'explanation': 'A lower treated-to-control ATP luminance ratio indicates greater drug sensitivity; the comparison table reports Sensitive versus Resistant calls.'},
    'threshold_rule': {'value': 'categorical', 'evidence': conf_refs, 'explanation': 'The evaluated source predictions are Sensitive versus Resistant calls; no global numeric cutoff is supplied.'},
    'threshold_timing': {'value': 'not_reported', 'evidence': ['article:p102'], 'explanation': 'The paper reports ROC evaluation but states that precise cutoff values were not yet defined.'},
    'patient_mapping': {'value': 'individual_available', 'evidence': [reported_ref], 'explanation': 'Patient identifiers and matched LCO results are available in the supplemental comparison table.'},
    'regimen_match': {'value': 'matched', 'evidence': [reported_ref], 'explanation': 'Only cases whose clinical regimens were identical to the LCO-DST regimen were included.'},
    'n_units': {'value': 54, 'evidence': [reported_ref, conf_acc_ref], 'explanation': 'Fifty-four matched LCO treatment comparisons; the published confusion matrix sums to 54.'},
    'split': {'value': 'same_cohort', 'evidence': [reported_ref, 'article:p102'], 'explanation': 'A real-world observational cohort with no separate held-out validation cohort.'}
}

CONTRACT = {
    'status': 'computed' if ok else 'blocked',
    'fields': fields,
    'headline': {
        'metric': 'accuracy',
        'reported': 0.8333333333333334,
        'reported_evidence': [reported_ref, conf_acc_ref],
        'threshold': None,
        'op': '==',
        'score_direction': 'higher',
        'records': records,
        'blocked_reason': None if ok else 'Could not identify 54 row-level source records with independently referenced LCO Sensitive/Resistant predictions and clinical PR/PD outcomes; parsed rows=%s and confusion=%s.' % (len(candidates), cm)
    },
    'notes': ['Published confusion matrix: Sensitive/PR=21, Sensitive/PD=5, Resistant/PR=4, Resistant/PD=24; accuracy=(21+24)/54=0.8333333.', 'Clinical sensitivity and specificity in the article are 84.0% and 82.8%, respectively.']
}"}
